"#include "diagnostics.h"
#include <Wire.h>
#include <esp_flash.h>

void diagnostics_init() {
    // Configure dock sense pin with internal pullup
    // LOW = Docked (cradle bridges P3 to P2/GND)
    // HIGH = Undocked (floating pin held at 3.3V)
    pinMode(PIN_DOCK_SENSE, INPUT_PULLUP);

    // Initialize I2C with strict bus timeout to prevent lockup on floating/shorted bus
    Wire.begin(PIN_I2C_SDA, PIN_I2C_SCL, I2C_BUS_FREQ_HZ);
    Wire.setTimeOut(I2C_TIMEOUT_MS);
}

void diagnostics_print_banner() {
    Serial.println();
    Serial.println("==================================================");
    Serial.println("  MOCHI BOT V1 - MILESTONE 0 DIAGNOSTICS");
    Serial.printf("  Firmware : %s\n", FIRMWARE_VERSION);
    Serial.printf("  Target   : %s\n", BUILD_TARGET);
    Serial.println("==================================================");
}

