        case FM_DIO:       return "DIO (Dual I/O)";
        case FM_DOUT:      return "DOUT (Dual Output)";
        case FM_FAST_READ: return "FAST_READ";
        case FM_SLOW_READ: return "SLOW_READ";
        default:           return "UNKNOWN";
    }
}

