"#pragma once

#include <Arduino.h>

// ============================================================================
// Mochi Bot V1 - Milestone 3 Audio Output & Tone Synthesizer
// Controls audio playback through the MAX98357A Class-D amplifier.
// Implements safe sequential bus switching with the INMP441 microphone
// to guarantee zero acoustic self-triggering and bounded power draw.
// ============================================================================

// Initializes the audio output subsystem
void audio_output_init();

// Synthesizes and plays a cheerful dual-tone chirp response (988 Hz -> 1318 Hz)
// Sequentially switches I2S bus to TX, plays tone, allows DMA drain, and restores RX.
bool audio_play_chirp();

// Returns whether audio playback is currently active
bool audio_is_playing();
"

"#include "audio_output.h"
#include "i2s_bus.h"
#include "sensors/clap_detector.h"
#include "app_state.h"
#include <cmath>

static bool s_is_playing = false;

constexpr uint32_t SAMPLE_RATE = 16000;
constexpr int16_t PEAK_AMPLITUDE = 6000; // Safe, balanced output volume

void audio_output_init() {
    s_is_playing = false;
    Serial.println("[AUDIO] Audio Output subsystem initialized.");
}

bool audio_is_playing() {
    return s_is_playing;
}

bool audio_play_chirp() {
    if (s_is_playing) {
        return false;
    }

    s_is_playing = true;

    // Suppress clap detector for tone duration (200 ms) + acoustic reverberation margin (550 ms)
    clap_detector_suppress(750);

    // 1. Release I2S bus from RX capture mode
    i2s_bus_stop();

    // 2. Initialize I2S bus for TX playback on MAX98357A (GPIO11 DIN)
    if (!i2s_bus_start_tx()) {
        Serial.println("[AUDIO] ERROR: Failed to switch I2S to TX mode.");
        s_is_playing = false;
        if (!app_state_is_display_sleeping()) {
            i2s_bus_start_rx();
        }
        return false;
    }

    // ------------------------------------------------------------------------
    // Tone 1: B5 (988 Hz) for 80 ms (1280 samples = 8 chunks of 160)
    // Tone 2: E6 (1318 Hz) for 120 ms (1920 samples = 12 chunks of 160)
    // Total duration: 200 ms (3200 samples = 20 chunks)
    // ------------------------------------------------------------------------
    constexpr size_t CHUNK_SIZE = 160;
    int16_t chunk_buf[CHUNK_SIZE];

    double phase = 0.0;
    double phase_inc1 = (2.0 * M_PI * 987.77) / SAMPLE_RATE;
    double phase_inc2 = (2.0 * M_PI * 1318.51) / SAMPLE_RATE;

